using System;
using UnityEngine;
using Framework.Input;
using Framework.Movement;
using Game.Input;
using Game.Stage;

namespace Game.Character
{
    /// <summary>
    /// 迷路内のプレイヤーを制御するクラス。
    ///
    /// 入力取得、移動方向の決定、宝石・アイテム取得、
    /// ステージ状態に応じた移動制御を担当する。
    ///
    /// 実際の移動処理はGridMovementControllerへ委譲する。
    /// </summary>
    [DisallowMultipleComponent]
    [RequireComponent(typeof(GridMovementController))]
    public class MazePlayerController : MonoBehaviour
    {
        #region Inspector Fields

        [Header("移動設定")]

        /// <summary>プレイヤーの基本移動速度。</summary>
        [SerializeField]
        [Min(0.1f)]
        [Tooltip("1秒間に移動するセル数")]
        private float baseMoveSpeed = 5f;

        /// <summary>方向入力のデッドゾーン。</summary>
        [SerializeField]
        [Range(0f, 0.99f)]
        [Tooltip("方向入力を無視する範囲")]
        private float deadZone = 0.3f;

        /// <summary>斜め入力時の方向優先設定。</summary>
        [SerializeField]
        [Tooltip("斜め入力時に優先する方向")]
        private DirectionPriority directionPriority =
            DirectionPriority.PreviousDirection;

        [Header("取得設定")]

        /// <summary>宝石を自動取得するか。</summary>
        [SerializeField]
        [Tooltip("セル到達時に宝石を自動取得する")]
        private bool autoCollectGem = true;

        /// <summary>アイテムを自動取得するか。</summary>
        [SerializeField]
        [Tooltip("セル到達時にアイテムを自動取得する")]
        private bool autoCollectItem = true;

        #endregion

        #region Runtime Fields

        /// <summary>汎用グリッド移動コンポーネント。</summary>
        private GridMovementController movement;

        /// <summary>現在のステージ管理クラス。</summary>
        private MazeStageManager stageManager;

        /// <summary>プレイヤーの入力取得先。</summary>
        private IInputProvider<GameInputAction> inputProvider;

        /// <summary>初期化対象となったステージ情報。</summary>
        private MazeStageGenerationResult boundStage;

        /// <summary>最後に取得した有効な入力方向。</summary>
        private Vector2Int previousInputDirection;

        /// <summary>プレイヤーの初期化状態。</summary>
        private bool isInitialized;

        /// <summary>移動速度に適用する倍率。</summary>
        private float speedMultiplier = 1f;

        #endregion

        #region Properties

        /// <summary>初期化が完了しているか。</summary>
        public bool IsInitialized => isInitialized;

        /// <summary>グリッド移動コンポーネント。</summary>
        public GridMovementController Movement => movement;

        /// <summary>現在到達しているセル座標。</summary>
        public Vector2Int CurrentCell =>
            movement != null
                ? movement.CurrentCell
                : Vector2Int.zero;

        /// <summary>現在の移動方向。</summary>
        public Vector2Int CurrentDirection =>
            movement != null
                ? movement.CurrentDirection
                : Vector2Int.zero;

        /// <summary>現在の基本移動速度。</summary>
        public float BaseMoveSpeed => baseMoveSpeed;

        /// <summary>現在の移動速度倍率。</summary>
        public float SpeedMultiplier => speedMultiplier;

        /// <summary>倍率適用後の移動速度。</summary>
        public float CurrentMoveSpeed =>
            baseMoveSpeed * speedMultiplier;

        /// <summary>プレイヤーが行動可能な状態か。</summary>
        public bool CanAct =>
            isInitialized &&
            isActiveAndEnabled &&
            stageManager != null &&
            stageManager.IsPlaying &&
            ReferenceEquals(
                boundStage,
                stageManager.StageResult);

        #endregion

        #region Events

        /// <summary>
        /// プレイヤーがセルの中心へ到達した際のイベント。
        /// 引数は到達したセル座標。
        /// </summary>
        public event Action<Vector2Int> CellEntered;

        /// <summary>
        /// プレイヤーが宝石を取得した際のイベント。
        /// 引数は取得したセル座標。
        /// </summary>
        public event Action<Vector2Int> GemCollected;

        /// <summary>
        /// プレイヤーがアイテムを取得した際のイベント。
        /// 引数は取得したセル座標。
        /// </summary>
        public event Action<Vector2Int> ItemCollected;

        /// <summary>
        /// アイテム使用が要求された際のイベント。
        /// 実際のアイテム効果は外部クラスが処理する。
        /// </summary>
        public event Action ItemUseRequested;

        /// <summary>
        /// 召喚が要求された際のイベント。
        /// 実際の召喚処理は外部クラスが担当する。
        /// </summary>
        public event Action SummonRequested;

        #endregion

        #region Unity Methods

        /// <summary>コンポーネント生成時の処理。</summary>
        private void Awake()
        {
            movement =
                GetComponent<GridMovementController>();

            // 移動更新の順序をPlayer側で管理する。
            movement.AutoUpdate = false;
        }

        /// <summary>コンポーネント有効化時の処理。</summary>
        private void OnEnable()
        {
            if (isInitialized)
            {
                SynchronizeMovementState();
            }
        }

        /// <summary>プレイヤーの毎フレーム更新処理。</summary>
        private void Update()
        {
            if (!CanAct)
            {
                return;
            }

            ProcessDirectionInput();
            ProcessActionInput();

            // アイテム使用などによってステージ状態が
            // 変化する可能性があるため再確認する。
            if (!CanAct)
            {
                return;
            }

            // 入力取得後に移動処理を実行する。
            movement.Tick(Time.deltaTime);
        }

        /// <summary>コンポーネント無効化時の処理。</summary>
        private void OnDisable()
        {
            if (movement != null)
            {
                movement.Pause();
            }
        }

        /// <summary>コンポーネント破棄時の処理。</summary>
        private void OnDestroy()
        {
            Shutdown();
        }

        #endregion

        #region Initialization Methods

        /// <summary>
        /// プレイヤーを指定されたステージへ接続する。
        /// </summary>
        /// <param name="manager">ステージ管理クラス</param>
        /// <param name="provider">入力取得先</param>
        /// <param name="spawnPosition">初期セル座標</param>
        /// <returns>初期化に成功した場合はtrue</returns>
        public bool Initialize(
            MazeStageManager manager,
            IInputProvider<GameInputAction> provider,
            Vector2Int spawnPosition)
        {
            if (manager == null ||
                provider == null ||
                !provider.IsInitialized ||
                !manager.HasStage ||
                manager.CoordinateConverter == null)
            {
                Debug.LogError(
                    "プレイヤーの初期化に必要な情報が不足しています。",
                    this);

                return false;
            }

            if (!manager.IsWalkable(spawnPosition))
            {
                Debug.LogError(
                    $"初期位置が通行できません：{spawnPosition}",
                    this);

                return false;
            }

            Shutdown();

            if (movement == null)
            {
                movement =
                    GetComponent<GridMovementController>();
            }

            try
            {
                stageManager = manager;
                inputProvider = provider;
                boundStage = manager.StageResult;

                speedMultiplier = 1f;
                previousInputDirection = Vector2Int.zero;

                // Spawnerが設定したZ座標を維持する。
                Vector3 cellCenter =
                    manager.CoordinateConverter
                        .GetCellCenterWorld(spawnPosition);

                float zOffset =
                    transform.position.z - cellCenter.z;

                movement.AutoUpdate = false;

                movement.MoveSpeed = CurrentMoveSpeed;

                movement.Initialize(
                    manager.CoordinateConverter,
                    CanEnterCell,
                    spawnPosition,
                    zOffset);

                movement.CellReached += OnCellReached;

                stageManager.StateChanged +=
                    OnStageStateChanged;

                isInitialized = true;

                SynchronizeMovementState();

                return true;
            }
            catch (Exception exception)
            {
                Shutdown();

                Debug.LogException(exception, this);

                return false;
            }
        }

        /// <summary>
        /// プレイヤー制御を終了して参照を解除する。
        /// </summary>
        public void Shutdown()
        {
            isInitialized = false;

            if (movement != null)
            {
                movement.CellReached -= OnCellReached;

                movement.Pause();
                movement.ClearRequestedDirection();
            }

            if (stageManager != null)
            {
                stageManager.StateChanged -=
                    OnStageStateChanged;
            }

            stageManager = null;
            inputProvider = null;
            boundStage = null;

            previousInputDirection = Vector2Int.zero;
        }

        #endregion

        #region Input Methods

        /// <summary>
        /// 方向入力を取得して移動方向を予約する。
        /// </summary>
        private void ProcessDirectionInput()
        {
            if (inputProvider == null ||
                !inputProvider.IsInputEnabled)
            {
                return;
            }

            Vector2 input =
                inputProvider.GetVector2(
                    GameInputAction.Move);

            Vector2Int direction =
                InputDirectionUtility.ToFourDirection(
                    input,
                    deadZone,
                    directionPriority,
                    previousInputDirection);

            // 入力を離しても現在の方向へ進み続ける。
            // 予約済みの方向も取り消さない。
            if (direction == Vector2Int.zero)
            {
                return;
            }

            previousInputDirection = direction;

            RequestDirection(direction);
        }

        /// <summary>
        /// アイテム使用・召喚入力を処理する。
        /// </summary>
        private void ProcessActionInput()
        {
            if (inputProvider == null ||
                !inputProvider.IsInputEnabled)
            {
                return;
            }

            if (inputProvider.GetButtonDown(
                GameInputAction.UseItem))
            {
                ItemUseRequested?.Invoke();
            }

            if (!CanAct)
            {
                return;
            }

            if (inputProvider.GetButtonDown(
                GameInputAction.Summon))
            {
                SummonRequested?.Invoke();
            }
        }

        /// <summary>
        /// 指定された方向への移動を予約する。
        ///
        /// キーボード以外の操作や自動テストからも利用できる。
        /// </summary>
        /// <param name="direction">予約する移動方向</param>
        /// <returns>予約に成功した場合はtrue</returns>
        public bool RequestDirection(Vector2Int direction)
        {
            if (!CanAct)
            {
                return false;
            }

            return movement.RequestDirection(direction);
        }

        #endregion

        #region Movement Methods

        /// <summary>
        /// 指定されたセルへ移動可能か確認する。
        /// </summary>
        /// <param name="position">確認するセル座標</param>
        /// <returns>通行可能な場合はtrue</returns>
        private bool CanEnterCell(Vector2Int position)
        {
            return stageManager != null &&
                   ReferenceEquals(
                       boundStage,
                       stageManager.StageResult) &&
                   stageManager.IsWalkable(position);
        }

        /// <summary>
        /// プレイヤーの基本移動速度を変更する。
        /// </summary>
        /// <param name="speed">変更後の基本移動速度</param>
        public void SetBaseMoveSpeed(float speed)
        {
            ValidateSpeed(speed, nameof(speed));

            baseMoveSpeed = speed;

            ApplyMoveSpeed();
        }

        /// <summary>
        /// 移動速度の倍率を変更する。
        /// 加速アイテムなどから利用する。
        /// </summary>
        /// <param name="multiplier">変更後の速度倍率</param>
        public void SetSpeedMultiplier(float multiplier)
        {
            ValidateSpeed(
                multiplier,
                nameof(multiplier));

            speedMultiplier = multiplier;

            ApplyMoveSpeed();
        }

        /// <summary>移動速度倍率を通常状態へ戻す。</summary>
        public void ResetSpeedMultiplier()
        {
            speedMultiplier = 1f;

            ApplyMoveSpeed();
        }

        /// <summary>
        /// 現在の速度設定を移動コンポーネントへ反映する。
        /// </summary>
        private void ApplyMoveSpeed()
        {
            if (movement != null)
            {
                movement.MoveSpeed = CurrentMoveSpeed;
            }
        }

        /// <summary>
        /// 速度設定が有効な値か確認する。
        /// </summary>
        /// <param name="value">検証する値</param>
        /// <param name="parameterName">引数名</param>
        private static void ValidateSpeed(
            float value,
            string parameterName)
        {
            if (float.IsNaN(value) ||
                float.IsInfinity(value) ||
                value < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    parameterName);
            }
        }

        #endregion

        #region Collection Methods

        /// <summary>
        /// プレイヤーがセルの中心へ到達した際の処理。
        /// </summary>
        /// <param name="position">到達したセル座標</param>
        private void OnCellReached(Vector2Int position)
        {
            if (!CanAct)
            {
                return;
            }

            CellEntered?.Invoke(position);

            if (!CanAct)
            {
                return;
            }

            // 宝石の取得はステージ管理側へ委譲する。
            if (autoCollectGem &&
                stageManager.TryCollectGem(position))
            {
                GemCollected?.Invoke(position);
            }

            // 最後の宝石を取得した場合、
            // この時点でステージクリアになっている。
            if (!CanAct)
            {
                return;
            }

            // アイテム取得もステージ管理側へ委譲する。
            if (autoCollectItem &&
                stageManager.TryCollectItem(position))
            {
                ItemCollected?.Invoke(position);
            }
        }

        #endregion

        #region Stage State Methods

        /// <summary>
        /// ステージ状態変更時の処理。
        /// </summary>
        /// <param name="previousState">変更前の状態</param>
        /// <param name="newState">変更後の状態</param>
        private void OnStageStateChanged(
            MazeStageState previousState,
            MazeStageState newState)
        {
            SynchronizeMovementState();
        }

        /// <summary>
        /// ステージ状態とプレイヤーの移動状態を同期する。
        /// </summary>
        private void SynchronizeMovementState()
        {
            if (movement == null)
            {
                return;
            }

            if (CanAct)
            {
                movement.Resume();
            }
            else
            {
                // 状態変更と同時に移動を停止する。
                // ポーズ時はセル間の移動進捗を維持する。
                movement.Pause();
            }
        }

        #endregion
    }
}
